const s=(a=document)=>{a.querySelectorAll("[data-ellipsis]").forEach(t=>{const e=Number.parseInt(t.dataset.ellipsis,10),i=Number.parseFloat(t.dataset.ellipsisBp);if(!Number.isFinite(e)||e<=0)return;t.dataset.ellipsisOriginal||(t.dataset.ellipsisOriginal=t.textContent?.trim()||"");const n=t.dataset.ellipsisOriginal;if(!(Number.isFinite(i)&&i>0?window.innerWidth<=i:!0)){t.textContent=n;return}if(n.length<=e){t.textContent=n;return}t.textContent=`${n.slice(0,e).trimEnd()}...`})};document.readyState==="loading"?document.addEventListener("DOMContentLoaded",()=>s()):s();window.addEventListener("resize",()=>s());
